mapper.select:
SELECT r.reservation_id AS reservationId,
r.status         AS status,
s.slot_id        AS slotId,
s.resource_id    AS resourceId,
s.start_time     AS startTime,
s.end_time       AS endTime,
res.name         AS resourceName
FROM reservation r JOIN resource_slot s ON s.slot_id = r.slot_id
LEFT JOIN `resource` res ON res.resource_id = s.resource_id
WHERE r.user_id = #{userId}
AND s.slot_date = #{slotDate}
AND s.start_time < #{endTime}
AND s.end_time > #{startTime}
AND r.status IN

    #{statusItem}


    AND r.reservation_id != #{excludeReservationId}

LIMIT 1

mapper.update:
UPDATE reservation
SET status        = #{target},
    active_key    = IF(#{target} IN ('PENDING', 'CONFIRMED'), active_key, NULL),
    cancelled_at  = IF(#{target} = 'CANCELLED', #{now}, cancelled_at),
    completed_at  = IF(#{target} = 'COMPLETED', #{now}, completed_at),
    updated_at    = #{now}
WHERE reservation_id = #{reservationId}
  AND status = #{expected}

mapper.select:
SELECT r.*
FROM reservation r JOIN resource_slot s ON s.slot_id = r.slot_id
WHERE r.status = 'CONFIRMED'
  AND TIMESTAMP(s.slot_date, s.end_time) < #{now}
ORDER BY r.reservation_id
LIMIT #{limit}
